.message-input-area,
.thread-input-area {
    display: flex;
    align-items: flex-end;
    gap: 8px;
    padding: 12px 20px;
    border-top: 1px solid #e1e1e1;
    flex-shrink: 0;
}

.message-input-area textarea,
.thread-input-area textarea {
    flex: 1;
    resize: none;
    border: 1px solid #ccc;
    border-radius: 6px;
    padding: 8px 12px;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
    min-height: 38px;
    max-height: 120px;
}

.message-input-area textarea:focus,
.thread-input-area textarea:focus {
    border-color: #1264a3;
    box-shadow: 0 0 0 1px #1264a3;
}

.send-btn {
    background: #007a5a;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 8px 16px;
    font-weight: 600;
    font-size: 0.85rem;
    cursor: pointer;
    white-space: nowrap;
    height: 38px;
}

.send-btn:hover:not(:disabled) {
    background: #005e45;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: default;
}

.no-channel-selected {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #999;
    font-size: 1.1rem;
}

/* ───── THREAD PANEL ───── */

.thread-panel {
    width: 25%;
    min-width: 280px;
    background: #fff;
    border-left: 1px solid #e1e1e1;
    display: flex;
    flex-direction: column;
