@page "/chat"
@layout ChatLayout
@using sv_5218774bea7b4a0da53f5e48c4208b78.Services
@inject IChatService ChatService
@inject IJSRuntime JS
@rendermode InteractiveServer

<div class="chat-container">
    @* ───── LEFT SIDEBAR ───── *@
    <aside class="channel-sidebar">
        <div class="sidebar-header">
            <h3>Channels</h3>
        </div>
        <ul class="channel-list">
            @if (_channels is not null)
            {
                @foreach (var channel in _channels)
                {
                    <li class="channel-item @(channel.Id == _activeChannelId ? "active" : "")"
                        @onclick="() => SelectChannelAsync(channel)">
                        <div class="channel-name"># @channel.Name</div>
                        <div class="channel-desc">@TruncateDescription(channel.Description)</div>
                        @if (channel.UnreadCount > 0)
                        {
                            <span class="unread-badge">@channel.UnreadCount</span>
                        }
                    </li>
                }
            }
        </ul>
    </aside>

    @* ───── MAIN MESSAGE AREA ───── *@
    <section class="message-area @(_threadOpen ? "" : "expanded")">
        @if (_activeChannel is not null)
        {
            <div class="message-header">
                <h2># @_activeChannel.Name</h2>
                <p>@_activeChannel.Description</p>
            </div>

            <div class="message-list" @ref="_messageListRef" @onscroll="OnMessageListScroll">
                @if (_loadingMore)
                {
                    <div class="loading-indicator">Loading older messages…</div>
                }
                @if (_messages is not null)
                {
                    @foreach (var msg in _messages)
                    {
                        <div class="message-row" @onmouseenter="() => _hoveredMessageId = msg.Id"
                             @onmouseleave="() => _hoveredMessageId = null">
                            <div class="message-bubble">
                                <div class="message-meta">
                                    <span class="author">@msg.Author</span>
                                    <span class="timestamp">@FormatRelativeTime(msg.SentAt)</span>
                                </div>
                                <div class="message-content">@msg.Content</div>

                                @if (msg.Reactions.Count > 0)
                                {
                                    <div class="reaction-bar">
                                        @foreach (var reaction in msg.Reactions)
                                        {
                                            <button class="reaction-badge" @onclick="() => AddReactionAsync(msg.Id, reaction.Emoji)"
                                                    title="@string.Join(", ", reaction.Users)">
                                                @reaction.Emoji @reaction.Users.Count
                                            </button>
                                        }
                                    </div>
                                }

                                @if (_threadSummaries.TryGetValue(msg.Id, out var summary))
                                {
                                    <button class="thread-link" @onclick="() => OpenThreadAsync(msg.Id)">
                                        @summary.ReplyCount @(summary.ReplyCount == 1 ? "reply" : "replies")
                                        &middot; Last @FormatRelativeTime(summary.LastReplyAt)
                                    </button>
                                }
                            </div>

                            @if (_hoveredMessageId == msg.Id)
                            {
                                <div class="message-actions">
                                    <button class="action-btn" @onclick="() => OpenThreadAsync(msg.Id)" title="Reply in thread">
                                        💬
                                    </button>
                                    <button class="action-btn" @onclick="() => ToggleEmojiPicker(msg.Id)"
                                            title="Add reaction">
                                        😊
                                    </button>
                                </div>
                                @if (_emojiPickerMessageId == msg.Id)
                                {
                                    <div class="emoji-picker">
                                        @foreach (var emoji in _commonEmojis)
                                        {
                                            <button class="emoji-option" @onclick="() => AddReactionAsync(msg.Id, emoji)">
                                                @emoji
                                            </button>
                                        }
                                    </div>
                                }
                            }
                        </div>
                    }
                }
            </div>

            <div class="message-input-area">
                <textarea @bind="_newMessage" @bind:event="oninput"
                          placeholder="Message #@_activeChannel.Name"
                          @onkeydown="OnMainKeyDown"
                          rows="1"></textarea>
                <button class="send-btn" @onclick="SendMainMessageAsync" disabled="@string.IsNullOrWhiteSpace(_newMessage)">
                    Send
                </button>
            </div>
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </section>

    @* ───── RIGHT THREAD PANEL ───── *@
    @if (_threadOpen && _threadRootMessage is not null)
    {
        <aside class="thread-panel">
            <div class="thread-header">
                <h3>Thread</h3>
                <button class="close-btn" @onclick="CloseThread" title="Close thread">✕</button>
            </div>
            <div class="thread-root-quote">
                <span class="author">@_threadRootMessage.Author</span>
                <p>@_threadRootMessage.Content</p>
            </div>
            <div class="thread-replies">
                @if (_threadMessages is not null)
                {
                    @foreach (var reply in _threadMessages)
                    {
                        <div class="thread-reply">
                            <div class="message-meta">
                                <span class="author">@reply.Author</span>
                                <span class="timestamp">@FormatRelativeTime(reply.SentAt)</span>
                            </div>
                            <div class="message-content">@reply.Content</div>
                        </div>
                    }
                }
            </div>
            <div class="thread-input-area">
                <textarea @bind="_threadReply" @bind:event="oninput"
                          placeholder="Reply…"
                          @onkeydown="OnThreadKeyDown"
                          rows="1"></textarea>
                <button class="send-btn" @onclick="SendThreadReplyAsync" disabled="@string.IsNullOrWhiteSpace(_threadReply)">
                    Reply
                </button>
            </div>
        </aside>
    }
</div>

@code {
    private List<Channel>? _channels;
    private List<Message>? _messages;
    private List<Message>? _threadMessages;
    private Message? _threadRootMessage;
    private Dictionary<int, ThreadSummary> _threadSummaries = new();
    private Channel? _activeChannel;
    private int? _activeChannelId;

    private bool _threadOpen;
    private int? _hoveredMessageId;
    private int? _emojiPickerMessageId;
    private int? _activeThreadRootId;

    private string _newMessage = "";
    private string _threadReply = "";

    private bool _loadingMore;
    private bool _allMessagesLoaded;
    private const int PageSize = 30;

    private ElementReference _messageListRef;

    private readonly string[] _commonEmojis = ["👍", "❤️", "😂", "🎉", "🤔", "👀"];

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannelAsync(_channels[0]);
        }
    }

    private async Task SelectChannelAsync(Channel channel)
    {
        _activeChannel = channel;
        _activeChannelId = channel.Id;
        _allMessagesLoaded = false;
        _emojiPickerMessageId = null;

        _messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        await ChatService.MarkChannelReadAsync(channel.Id);
        BuildThreadSummaries();

        // Refresh channel list to update unread counts
        _channels = await ChatService.GetChannelsAsync();

        await ScrollToBottomAsync();
    }

    private void BuildThreadSummaries()
    {
        _threadSummaries.Clear();
        if (_messages is null) return;

        var repliesByRoot = _messages
            .Where(m => m.ReplyToId.HasValue)
            .GroupBy(m => m.ReplyToId!.Value);

        foreach (var group in repliesByRoot)
        {
            _threadSummaries[group.Key] = new ThreadSummary(
                group.Key,
                group.Count(),
                group.Max(m => m.SentAt)
            );
        }
    }

    private async Task SendMainMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(_newMessage) || _activeChannelId is null) return;

        var sent = await ChatService.SendMessageAsync(_activeChannelId.Value, _newMessage.Trim(), null);
        _newMessage = "";
        _messages ??= new();
        _messages.Add(sent);
        await ScrollToBottomAsync();
    }

    private async Task OnMainKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendMainMessageAsync();
        }
    }

    private async Task OnMessageListScroll()
    {
        if (_loadingMore || _allMessagesLoaded || _activeChannelId is null || _messages is null) return;

        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop < 50)
        {
            _loadingMore = true;
            StateHasChanged();

            var older = await ChatService.GetMessagesAsync(_activeChannelId.Value, _messages.Count, PageSize);
            if (older.Count == 0)
            {
                _allMessagesLoaded = true;
            }
            else
            {
                _messages.InsertRange(0, older);
                BuildThreadSummaries();
            }

            _loadingMore = false;
        }
    }

    private async Task OpenThreadAsync(int rootMessageId)
    {
        _activeThreadRootId = rootMessageId;
        _threadRootMessage = _messages?.FirstOrDefault(m => m.Id == rootMessageId);
        _threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        _threadReply = "";
        _threadOpen = true;
        _emojiPickerMessageId = null;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadMessages = null;
        _activeThreadRootId = null;
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(_threadReply) || _activeChannelId is null || _activeThreadRootId is null) return;

        var reply = await ChatService.SendMessageAsync(_activeChannelId.Value, _threadReply.Trim(), _activeThreadRootId);
        _threadReply = "";
        _threadMessages ??= new();
        _threadMessages.Add(reply);

        // Update thread summary in main view
        if (_threadSummaries.TryGetValue(_activeThreadRootId.Value, out var existing))
        {
            _threadSummaries[_activeThreadRootId.Value] = existing with
            {
                ReplyCount = existing.ReplyCount + 1,
                LastReplyAt = reply.SentAt
            };
        }
        else
        {
            _threadSummaries[_activeThreadRootId.Value] = new ThreadSummary(
                _activeThreadRootId.Value, 1, reply.SentAt);
        }
    }

    private async Task OnThreadKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendThreadReplyAsync();
        }
    }

    private async Task AddReactionAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        _emojiPickerMessageId = null;

        // Refresh messages to show updated reactions
        if (_activeChannelId is not null && _messages is not null)
        {
            _messages = await ChatService.GetMessagesAsync(_activeChannelId.Value, 0, _messages.Count);
            BuildThreadSummaries();
        }
    }

    private void ToggleEmojiPicker(int messageId)
    {
        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
    }

    private async Task ScrollToBottomAsync()
    {
        await Task.Yield();
        await JS.InvokeVoidAsync("eval",
            "setTimeout(() => { const el = document.querySelector('.message-list'); if (el) el.scrollTop = el.scrollHeight; }, 50)");
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();

        return diff.TotalSeconds switch
        {
            < 60 => "just now",
            < 3600 => $"{(int)diff.TotalMinutes} min ago",
            < 86400 => $"{(int)diff.TotalHours}h ago",
            < 604800 => $"{(int)diff.TotalDays}d ago",
            _ => sentAt.ToString("MMM d, yyyy")
        };
    }

    private static string TruncateDescription(string description)
    {
        return description.Length > 40 ? description[..37] + "…" : description;
    }
}

